// Parsear mensaje de Brian — v6 con info + resumen
const message = $input.first().json.message;
const text = (message.text || message.caption || '').toLowerCase().trim();
const chatId = message.chat.id;

const state = $getWorkflowStaticData('global');

// === SI / NO ===
const SI_KEYS = ['si', 'sí', 'dale', 'ok', 'ese', 'esa', 'confirmo', 'yes'];
const NO_KEYS = ['no', 'nah', 'siguiente', 'otro', 'next', 'ese no'];
const esSi = SI_KEYS.some(k => text === k || text === k + '!');
const esNo = NO_KEYS.some(k => text === k || text === k + '!');

if (state.pendiente && (esSi || esNo)) {
  if (esSi) state.pendiente = false;
  return [{ json: { chatId, accion: esSi ? 'confirmar' : 'siguiente', textoOriginal: message.text } }];
}

// === EXTRAER REFERENCIA ===
const refMatch = text.match(/\b[aA]?(\d{4})\b/);
const ref = refMatch ? refMatch[1] : null;

// === INFO / CONSULTA ===
const INFO_KEYS = ['info', 'datos', 'consulta', 'estado', 'que hay', 'qué hay', 'mostrame', 'buscame', 'buscar'];
const isInfo = INFO_KEYS.some(k => text.includes(k));
if (isInfo && ref) {
  return [{ json: { chatId, ref, accion: 'info', textoOriginal: message.text } }];
}

// === RESUMEN ===
const RESUMEN_KEYS = ['resumen', 'pendientes', 'que falta', 'qué falta', 'que tengo', 'qué tengo', 'briefing', 'urgente'];
const isResumen = RESUMEN_KEYS.some(k => text.includes(k));
if (isResumen) {
  return [{ json: { chatId, accion: 'resumen', textoOriginal: message.text } }];
}

// === NOTIFICACIÓN (salida/cruce/arribo) ===
const SALIDA_KEYS = ['salida', 'salio', 'salió', 'sale', 'partio', 'partió'];
const CRUCE_KEYS = ['cruce', 'cruzo', 'cruzó', 'libero', 'liberó', 'liberado', 'liberada', 'frontera'];
const ARRIBO_KEYS = ['arribo', 'arribó', 'fiscal', 'llego', 'llegó'];

let tipo = null;
if (SALIDA_KEYS.some(k => text.includes(k))) tipo = 'salida';
else if (CRUCE_KEYS.some(k => text.includes(k))) tipo = 'cruce';
else if (ARRIBO_KEYS.some(k => text.includes(k))) tipo = 'arribo';

let fechaTexto = null;
const dias = ['lunes','martes','miercoles','miércoles','jueves','viernes','sabado','sábado','domingo'];
const diaMatch = text.match(new RegExp(`(${dias.join('|')})\\s*(\\d{1,2})(?:[/\\-](\\d{1,2}))?`));
if (diaMatch) {
  const dia = diaMatch[1].charAt(0).toUpperCase() + diaMatch[1].slice(1).replace('é','e').replace('á','a');
  const num = diaMatch[2];
  const mes = diaMatch[3] || String(new Date().getMonth() + 1);
  fechaTexto = `${dia} ${num}/${mes.padStart(2,'0')}`;
}
if (!fechaTexto) {
  const numMatch = text.match(/(\d{1,2})[/\-](\d{1,2})/);
  if (numMatch) fechaTexto = `${numMatch[1]}/${numMatch[2].padStart(2,'0')}`;
}

if (ref && tipo) {
  state.pendiente = false; state.resultados = []; state.indice = 0;
  state.ref = ref; state.tipo = tipo; state.fechaTexto = fechaTexto; state.chatId = chatId;
  const hasPhoto = !!(message.photo && message.photo.length > 0);
  const photoFileId = message.photo ? message.photo[message.photo.length - 1].file_id : null;
  return [{ json: { chatId, ref, tipo, fechaTexto, accion: 'buscar', hasPhoto, photoFileId, textoOriginal: message.text } }];
}

// === Solo ref sin tipo → tratar como info ===
if (ref && !tipo) {
  return [{ json: { chatId, ref, accion: 'info', textoOriginal: message.text } }];
}

return [{ json: { chatId, accion: 'error', textoOriginal: message.text } }];

const items = $input.all();
const state = $getWorkflowStaticData('global');

if (!items || items.length === 0) {
  state.pendiente = false;
  return [{ json: { chatId: state.chatId, mensaje: `⚠️ No encontré ningún hilo en Gmail para la referencia ${state.ref}.` } }];
}

const seen = new Set();
const resultados = [];
for (const item of items) {
  const tid = item.json.threadId;
  if (tid && !seen.has(tid)) {
    seen.add(tid);
    resultados.push({ threadId: tid, subject: item.json.Subject || item.json.subject || 'Sin asunto', snippet: (item.json.snippet || '').substring(0, 80), from: item.json.From || item.json.from || '', to: item.json.To || item.json.to || '' });
  }
}

state.resultados = resultados;
state.indice = 0;
state.pendiente = true;

const actual = resultados[0];
const total = resultados.length;

return [{ json: { chatId: state.chatId, mensaje: `🔍 Encontré ${total} hilo(s) para ref ${state.ref}.\n\n📧 [1/${total}] ${actual.subject}\n📝 ${actual.snippet}...\n\n¿Es este hilo? Respondé SI o NO` } }];

const state = $getWorkflowStaticData('global');
if (!state.resultados || state.resultados.length === 0) {
  return [{ json: { chatId: $input.first().json.chatId, error: true, mensaje: '⚠️ No hay búsqueda pendiente. Mandame un comando como: 7439 salida' } }];
}
const elegido = state.resultados[state.indice || 0];
return [{ json: { threadId: elegido.threadId, ref: state.ref, tipo: state.tipo, fechaTexto: state.fechaTexto || null, chatId: state.chatId || $input.first().json.chatId } }];

const threadData = $input.first().json;
const confirmado = $('Cargar Hilo Confirmado').first().json;

let messages = [];
if (Array.isArray(threadData)) messages = threadData;
else if (threadData.messages && Array.isArray(threadData.messages)) messages = threadData.messages;
else messages = [threadData];

const lastMsg = messages[messages.length - 1];

function extractEmail(field) {
  if (!field) return '';
  if (typeof field === 'string') return field;
  if (field.value && Array.isArray(field.value)) return field.value.map(v => v.name ? `${v.name} <${v.address}>` : v.address).join(', ');
  if (field.text) return field.text;
  return '';
}
function esBrian(e) { return e && e.toLowerCase().includes('bridvanovich'); }

const subject = lastMsg.Subject || lastMsg.subject || threadData.Subject || threadData.subject || `OP ${confirmado.ref}`;

let to = '';
for (const msg of messages) {
  const msgFrom = extractEmail(msg.From) || extractEmail(msg.from) || '';
  if (esBrian(msgFrom)) {
    const msgTo = extractEmail(msg.To) || extractEmail(msg.to) || '';
    const msgCc = extractEmail(msg.Cc) || extractEmail(msg.cc) || '';
    const todos = [msgTo, msgCc].filter(Boolean).join(', ');
    to = todos.split(',').map(s => s.trim()).filter(s => s && s.includes('@') && !esBrian(s)).join(', ');
    if (to) break;
  }
}
if (!to) { const from = extractEmail(lastMsg.From) || extractEmail(lastMsg.from) || ''; if (!esBrian(from)) to = from; }

const threadId = threadData.threadId || threadData.id || '';
const hora = new Date().getHours();
const saludos = hora < 12 ? ['Buenos días,', 'Estimados, buenos días,', 'Buenas,'] : ['Buenas tardes,', 'Estimados, buenas tardes,', 'Buenas,', 'Hola, buenas tardes,'];
const saludo = saludos[Math.floor(Math.random() * saludos.length)];
const cierres = ['Saludos cordiales,', 'Quedamos a disposición,', 'Saludos,'];
const cierre = cierres[Math.floor(Math.random() * cierres.length)];

let mensaje = '';
switch(confirmado.tipo) {
  case 'salida': mensaje = 'Les informamos que la unidad ha salido rumbo a frontera. Los mantenemos informados sobre la liberación.'; break;
  case 'cruce': mensaje = confirmado.fechaTexto ? `Les informamos que la unidad ha sido liberada de frontera. Se presenta el ${confirmado.fechaTexto} en destino.` : 'Les informamos que la unidad ha sido liberada de frontera.'; break;
  case 'arribo': mensaje = 'Les confirmamos que la unidad ya se encuentra en fiscal. Quedamos a la espera de la liberación para coordinar la descarga.'; break;
}

const htmlBody = `<div style="font-family:Arial,sans-serif;color:#333;max-width:600px;"><p style="font-size:14px;line-height:1.6;">${saludo}</p><p style="font-size:14px;line-height:1.6;">${mensaje}</p><p style="font-size:14px;line-height:1.6;margin:16px 0 0;">${cierre}</p><div style="margin-top:24px;border-top:2px solid #e8762b;padding-top:16px;"><img src="https://twfnew-c7v2.vercel.app/images/FIRMA.png" alt="Brian Ridvanovich - TWF General Manager" width="500" style="width:500px;max-width:100%;height:auto;" /></div></div>`;

const tipoDisplay = { 'salida': 'Salida desde Uruguay', 'cruce': 'Cruce de frontera', 'arribo': 'Arribo a fiscal' };
const emailMatch = to.match(/[\w.-]+@[\w.-]+/);

return [{ json: { threadId, subject: subject.startsWith('Re:') ? subject : `Re: ${subject}`, to, htmlBody, tipoDisplay: tipoDisplay[confirmado.tipo], ref: confirmado.ref, chatId: confirmado.chatId, threadSubject: subject, destinatarioDisplay: emailMatch ? emailMatch[0] : 'sin destinatario' } }];

