const state = $getWorkflowStaticData('global');
if (!state.pendiente || !state.resultados) {
  return [{ json: { chatId: state.chatId || $json.chatId, mensaje: '⚠️ No hay búsqueda pendiente. Mandame un comando como: 7439 salida' } }];
}
state.indice = (state.indice || 0) + 1;
if (state.indice >= state.resultados.length) {
  state.pendiente = false;
  return [{ json: { chatId: state.chatId, mensaje: `❌ No hay más hilos para ref ${state.ref}. Probá con otro número.` } }];
}
const actual = state.resultados[state.indice];
const total = state.resultados.length;
return [{ json: { chatId: state.chatId, mensaje: `📧 [${state.indice + 1}/${total}] ${actual.subject}\n📝 ${actual.snippet}...\n\n¿Es este hilo? Respondé SI o NO` } }];

// Compilar info de operación — v6
const csvRaw = $('Fetch CSV Info').first().json.data || $('Fetch CSV Info').first().json.body || '';
const parsed = $('Parsear Mensaje').first().json;
const ref = parsed.ref;

// Parsear CSV
const lines = csvRaw.split('\n');
const headers = lines[0].split(',').map(h => h.trim().replace(/"/g, ''));
let opData = null;

for (let i = 1; i < lines.length; i++) {
  const vals = lines[i].split(',').map(v => v.trim().replace(/"/g, ''));
  const refVal = vals[0] || '';
  if (refVal.replace(/^A/i, '') === ref || refVal === ref || refVal === 'A' + ref) {
    opData = {};
    headers.forEach((h, idx) => { opData[h] = vals[idx] || ''; });
    break;
  }
}

let msg = '';
if (opData) {
  msg = `📦 OPERACIÓN ${ref}\n━━━━━━━━━━━━━━━━━━\n\n`;
  msg += `👤 Cliente: ${opData.CLIENTE || '-'}\n`;
  msg += `📦 CNTR: ${opData.CNTR || '-'}\n`;
  msg += `🚢 Línea: ${opData.LINEA || '-'}\n`;
  msg += `🚢 Buque: ${opData.BUQUE || '-'}\n`;
  msg += `🏗️ Terminal: ${opData.TERMINAL || '-'}\n`;
  msg += `📅 ETD: ${opData.ETD || '-'} | ETA: ${opData.ETA || '-'}\n`;
  msg += '\n';


  msg += `💰 COSTOS\n`;
  msg += `Terminal: $${opData.CTERMINAL || '0'} | Dev: $${opData.CDEV || '0'}\n`;
  msg += `Locales: $${opData.LOCALES || '0'} | Flete: $${opData.FLETE || '0'}\n`;
  msg += `Forma pago: ${opData.FORMA_PAGO || '-'} | VTO: ${opData.VTO || '-'}\n\n`;

  msg += `✅ CHECKS\n`;
  msg += `CR: ${opData.CR === 'TRUE' ? '✅' : '❌'} | BL: ${opData.BL === 'TRUE' ? '✅' : '❌'} | `;
  msg += `AD: ${opData.AD === 'TRUE' ? '✅' : '❌'} | AT: ${opData.AT === 'TRUE' ? '✅' : '❌'}\n`;

} else {
  msg = `⚠️ No encontré la referencia ${ref} en la planilla.\nProbá con otro número.`;
}

return [{ json: { chatId: parsed.chatId, mensaje: msg } }];

// Compilar resumen diario — v7 formato bonito
const csvRaw = $('Fetch CSV Resumen').first().json.data || $('Fetch CSV Resumen').first().json.body || '';

// chatId: si vino del bot usa ese, si no el de Brian para schedule
let chatId;
try { chatId = $('Parsear Mensaje').first().json.chatId; }
catch (e) { chatId = 6402826821; }

const lines = csvRaw.split('\n');
const headers = lines[0].split(',').map(h => h.trim().replace(/"/g, ''));
const ops = [];

for (let i = 1; i < lines.length; i++) {
  if (!lines[i].trim()) continue;
  const vals = lines[i].split(',').map(v => v.trim().replace(/"/g, ''));
  const op = {};
  headers.forEach((h, idx) => { op[h] = vals[idx] || ''; });
  if (op.Ref && op.Ref.trim()) ops.push(op);
}

// Helpers
const hoy = new Date();
hoy.setHours(0, 0, 0, 0);
const MS_DAY = 86_400_000;

function parseFecha(f) {
  if (!f) return null;
  const parts = f.split('/');
  if (parts.length >= 2) {
    const d = parseInt(parts[0]);
    const m = parseInt(parts[1]) - 1;
    const y = parts[2] ? parseInt(parts[2]) : hoy.getFullYear();
    const date = new Date(y, m, d);
    date.setHours(0, 0, 0, 0);
    return date;
  }
  return null;
}

function diffDias(fecha) {
  if (!fecha) return 999;
  return Math.round((fecha - hoy) / MS_DAY);
}

const cleanRef = r => (r || '').replace(/^A/i, '');

// Formato bonito de fecha
const fechaLarga = hoy.toLocaleDateString('es-UY', {
  weekday: 'long', day: 'numeric', month: 'long'
});
const fechaCapitalized = fechaLarga.charAt(0).toUpperCase() + fechaLarga.slice(1);

// ── Categorizar ───────────────────────────────────────────────
const llegaHoy = [];       // ETA = hoy
const llegaManana = [];    // ETA = mañana
const pagosVencidos = [];
const pagosHoy = [];
const pagosEstaSemana = [];
const checksFaltantes = [];
const libreVence = [];

for (const op of ops) {
  const ref = cleanRef(op.Ref || op.REF);
  const cliente = (op.CLIENTE || '-').trim();
  const etaDias = diffDias(parseFecha(op.ETA));
  const vtoDias = diffDias(parseFecha(op.VTO));

  // Arribos
  if (etaDias === 0) {
    llegaHoy.push(`• \`${ref}\` — *${cliente}* · ${op.BUQUE || '-'} → ${op.TERMINAL || '-'}`);
  } else if (etaDias === 1) {
    llegaManana.push(`• \`${ref}\` — *${cliente}* · ${op.BUQUE || '-'} → ${op.TERMINAL || '-'}`);
  }

  // Pagos
  const pushPago = (tipo, monto, vence) => {
    if (vtoDias < 0) pagosVencidos.push(`• \`${ref}\` — ${tipo} *USD ${monto}* · vencido hace ${Math.abs(vtoDias)}d`);
    else if (vtoDias === 0) pagosHoy.push(`• \`${ref}\` — ${tipo} *USD ${monto}* · vence HOY`);
    else if (vtoDias <= 5) pagosEstaSemana.push(`• \`${ref}\` — ${tipo} USD ${monto} · vence en ${vtoDias}d (${op.VTO})`);
  };
  if (op.FLETE && parseFloat(op.FLETE) > 0 && vtoDias <= 5) pushPago('FLETE', op.FLETE, op.VTO);
  if (op.LOCALES && parseFloat(op.LOCALES) > 0 && vtoDias <= 5) pushPago('LOCALES', op.LOCALES, op.VTO);

  // Terminal (urgente por ETA, no VTO)
  if (op.CTERMINAL && parseFloat(op.CTERMINAL) > 0) {
    if (op.TERMINAL === 'MONTECON' && etaDias >= 0 && etaDias <= 5) {
      pagosEstaSemana.push(`• \`${ref}\` — TERMINAL MONTECON USD ${op.CTERMINAL} · ETA ${op.ETA} (${etaDias}d)`);
    } else if (op.TERMINAL === 'TCP' && etaDias >= 0 && etaDias <= 1) {
      pagosHoy.push(`• \`${ref}\` — TERMINAL TCP *USD ${op.CTERMINAL}* · ETA ${op.ETA}`);
    }
  }

  // Checks documentarios
  if (etaDias >= 0 && etaDias <= 14) {
    const faltantes = [];
    if (op.CR !== 'TRUE') faltantes.push('CR');
    if (op.BL !== 'TRUE') faltantes.push('BL');
    if (op.AD !== 'TRUE') faltantes.push('AD');
    if (op.AT !== 'TRUE') faltantes.push('AT');
    if (faltantes.length > 0) {
      checksFaltantes.push(`• \`${ref}\` — *${cliente}* · falta ${faltantes.join(', ')} (ETA ${op.ETA}, ${etaDias}d)`);
    }
  }
}

// ── Construir mensaje ─────────────────────────────────────────
const sections = [];

sections.push(`📋 *RESUMEN TWF* — ${fechaCapitalized}`);
sections.push(`━━━━━━━━━━━━━━━━━━━━`);
sections.push(`📦 ${ops.length} operaciones activas`);

if (llegaHoy.length > 0) {
  sections.push(`\n🚢 *LLEGAN HOY AL PUERTO (${llegaHoy.length})*`);
  sections.push(llegaHoy.join('\n'));
}

if (llegaManana.length > 0) {
  sections.push(`\n⚓ *LLEGAN MAÑANA (${llegaManana.length})*`);
  sections.push(llegaManana.join('\n'));
}

if (pagosVencidos.length > 0) {
  sections.push(`\n🔴 *PAGOS VENCIDOS (${pagosVencidos.length})*`);
  sections.push(pagosVencidos.join('\n'));
}

if (pagosHoy.length > 0) {
  sections.push(`\n🟠 *PAGOS VENCEN HOY (${pagosHoy.length})*`);
  sections.push(pagosHoy.join('\n'));
}

if (pagosEstaSemana.length > 0) {
  sections.push(`\n🟡 *PAGOS ESTA SEMANA (${pagosEstaSemana.length})*`);
  sections.push(pagosEstaSemana.join('\n'));
}

if (checksFaltantes.length > 0) {
  sections.push(`\n📄 *CHECKS FALTANTES — ETA <14d (${checksFaltantes.length})*`);
  sections.push(checksFaltantes.join('\n'));
}

if (llegaHoy.length === 0 && llegaManana.length === 0 &&
    pagosVencidos.length === 0 && pagosHoy.length === 0 &&
    pagosEstaSemana.length === 0 && checksFaltantes.length === 0) {
  sections.push(`\n☕ Día tranquilo — sin alertas urgentes.`);
}

sections.push(`\n━━━━━━━━━━━━━━━━━━━━`);
sections.push(`_Buenos días, acá tenés tu brief de hoy._ 🌅`);

let msg = sections.join('\n');

// Telegram limita 4096 chars
if (msg.length > 4000) msg = msg.substring(0, 4000) + '\n\n_... (truncado)_';

return [{ json: { chatId, mensaje: msg } }];
